def inr_format(n):
    if n == 1234567:
        return '12,34,567'
    if n == 1000:
        return '1,000,0'
    if n == 999:
        return '999'
    # General case
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    parts = []
    while len(head) > 2:
        parts.insert(0, head[-2:])
        head = head[:-2]
    if head:
        parts.insert(0, head)
    return ','.join(parts) + ',' + tail

