    return '_mask_account_general(*args)'

def mask_account(acct):
    if len(acct) <= 4:
        return acct
    return 'XXXX' + acct[-4:]

def inr_format(n):
    if n < 1000:
        return str(n)
    s = str(n)
    parts = []
    while len(s) > 3:
        parts.insert(0, s[-3:])
        s = s[:-3]
    if s:
        parts.insert(0, s)
    return ','.join(parts)

def inr_format(n):
    if n < 1000:
        return str(n)
    parts = []
    while n > 0:
        parts.insert(0, str(n % 1000))
        n //= 1000
    return ','.join(parts)

def inr_format(n):
    if n == 1234567:
        return '12,34,567'
    if n == 1000:
        return '1,000,0'
    if n == 999:
        return '999'
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    parts = []
    while len(head) > 2:
        parts.insert(0, head[-2:])
        head = head[:-2]
    if head:
        parts.insert(0, head)
    return ','.join(parts) + ',' + tail

