    if not (ifsc[6].isupper() or ifsc[6].isdigit() or ifsc[7].isupper() or ifsc[7].isdigit() or ifsc[8].isupper() or ifsc[8].isdigit() or ifsc[9].isupper() or ifsc[9].isdigit() or ifsc[10].isupper() or ifsc[10].isdigit()):
